/* Koruk Asistan — Rubric Settings V2
 * Kriter/Proje araçlarının ayar kapısı.
 * Kişisel ayar: KorukLocalFirst IndexedDB meta.
 * Okul varsayılanı: mevcut oy_okulBilgileri/ayarlar, DeviceData üzerinden queue/sync.
 */
(function(global){
'use strict';
if(global.RubricSettingsService)return;
const KINDS={rubric:{local:'krtDagitimAyarlari',field:'kriterDagitimAyari'},project:{local:'projeDagitimAyarlari',field:'projeDegerlendirmeAyari'}};
const clone=v=>v==null?v:JSON.parse(JSON.stringify(v));
const uid=()=>global.AKTIF_KULLANICI?.uid||global.AppStore?.get?.('session.user')?.uid||'';
function def(kind){const d=KINDS[kind];if(!d)throw new Error('rubric-kind-gecersiz:'+kind);return d;}
async function ensureSchoolCache(){
 if(!global.SyncEngine||!global.COL?.okulBilgileri)return;
 global.SyncEngine.register('okulBilgileri',global.COL.okulBilgileri);
 if(uid())await global.SyncEngine.localHydrate(['okulBilgileri']);
}
function schoolDoc(){
 const rows=global.AppStore?.data?.('okulBilgileri');
 const row=Array.isArray(rows)?rows.find(x=>x?.id==='ayarlar'):null;
 if(row)return row;
 return global.okulBilgileriAyari&&typeof global.okulBilgileriAyari==='object'?global.okulBilgileriAyari:{};
}
async function personalGet(kind){
 const d=def(kind),u=uid();if(!u)return null;
 const key='rubric-settings:'+kind;
 const migratedKey=key+':legacy-migrated';
 const saved=await global.KorukLocalFirst?.meta?.(u,key);
 if(saved)return clone(saved);
 const migrated=await global.KorukLocalFirst?.meta?.(u,migratedKey);
 if(migrated===true)return null;
 try{
   const raw=global.localStorage?.getItem?.(d.local);
   if(raw){const value=JSON.parse(raw);await global.KorukLocalFirst?.meta?.(u,key,value);await global.KorukLocalFirst?.meta?.(u,migratedKey,true);global.localStorage?.removeItem?.(d.local);return clone(value);}
 }catch(e){console.warn('[RubricSettings/migrate]',kind,e?.message||e);}
 await global.KorukLocalFirst?.meta?.(u,migratedKey,true);
 return null;
}
async function personalSet(kind,value){
 const u=uid();if(!u)throw new Error('girissiz');def(kind);
 const key='rubric-settings:'+kind;
 await global.KorukLocalFirst.meta(u,key,clone(value));
 await global.KorukLocalFirst.meta(u,key+':legacy-migrated',true);
 global.dispatchEvent(new CustomEvent('koruk:rubric-settings-changed',{detail:{kind,scope:'personal'}}));
 return clone(value);
}
function schoolGet(kind){const d=def(kind);return clone(schoolDoc()?.[d.field]||null);}
async function schoolSet(kind,value){
 const d=def(kind),u=global.AKTIF_KULLANICI||global.AppStore?.get?.('session.user')||{};
 if(u.admin!==true)throw Object.assign(new Error('yetkisiz'),{code:'permission-denied'});
 if(!global.DeviceData||!global.COL?.okulBilgileri)throw new Error('DeviceData/okulBilgileri hazır değil.');
 await ensureSchoolCache();
 const current=schoolDoc();
 const next={...current,[d.field]:clone(value),id:'ayarlar',guncellenmeTarihi:new Date().toISOString()};
 await global.DeviceData.set('okulBilgileri',global.COL.okulBilgileri,'ayarlar',next,{merge:true});
 global.okulBilgileriAyari=next;
 global.dispatchEvent(new CustomEvent('koruk:rubric-settings-changed',{detail:{kind,scope:'school'}}));
 return clone(value);
}
async function resolve(kind,fallback){await ensureSchoolCache();return clone((await personalGet(kind))||schoolGet(kind)||fallback);}
async function clearPersonal(kind){const u=uid();if(!u)return;def(kind);const key='rubric-settings:'+kind;await global.KorukLocalFirst.meta(u,key,null);await global.KorukLocalFirst.meta(u,key+':legacy-migrated',true);global.dispatchEvent(new CustomEvent('koruk:rubric-settings-changed',{detail:{kind,scope:'personal-clear'}}));}
try{global.SyncEngine?.register?.('okulBilgileri',global.COL?.okulBilgileri);}catch(_){}
global.RubricSettingsService={KINDS:Object.freeze(clone(KINDS)),personalGet,personalSet,schoolGet,schoolSet,resolve,clearPersonal};
global.AppLoader?.loadScript?.('js/modules/student-attendance-legacy.js').catch?.(e=>console.warn('[StudentAttendanceLegacy load]',e?.message||e));
})(window);

/* ====================================================================
 * CLASSIC ÇİZELGELER PARITY
 * 708c82a görünür çizelge çalışma alanlarını local-first CizelgelerService
 * üzerine geri kurar. Yeni repository/veri modeli oluşturmaz.
 * ==================================================================== */
(function(global){
'use strict';
if(global.ClassicCizelgelerParity)return;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]||c));
const norm=v=>String(v||'').toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/ş/g,'s').replace(/ğ/g,'g').replace(/ü/g,'u').replace(/ö/g,'o').replace(/ç/g,'c').trim();
const arr=t=>{const v=global.AppStore?.data?.(t);return Array.isArray(v)?v:[]};
const teacherName=id=>{const o=arr('ogretmenler').find(x=>x.id===id);return o?`${o.ad||''} ${o.soyad||''}`.trim():'—'};
const className=id=>{const s=arr('siniflar').find(x=>x.id===id);return s?.ad||id||'—'};
const today=()=>{const d=new Date(),p=n=>String(n).padStart(2,'0');return`${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`};
const trDate=v=>{if(!v)return'';const p=String(v).split('-');return p.length===3?`${p[2]}.${p[1]}.${p[0]}`:String(v)};
const CONTROLS={
 sosyalKulupler:['Yıllık Plan','Toplum Hizm. Planı','Eki','Kas','Ara','Oca','Şub','Mar','Nis','May','Haz','Sene Sonu Rap.'],
 belirliGunler:['Yapıldı'],zumre:['1. Dönem','2. Dönem','Yıl Sonu'],sok:['1. Dönem','2. Dönem','Yıl Sonu'],
 bepPlani:['Yıllık Ders Planı','BEP Planı'],rehberlik:['Yıllık Çalışma Planı','Eki','Kas','Ara','Oca','Şub','Mar','Nis','May','Haz','1.Dönem Sonu Rap.','Sene Sonu Rap.'],
 maarifRapor:['Eyl','Eki','Kas','Ara','Oca','Şub','Mar','Nis','May','Haz']
};
const CFG={
 sosyalKulupler:{route:'Sosyal Kulüpler',title:'Sosyal Kulüpler',sub:'Teslim edilmesi gereken evrakları işaretleyin',add:'+ Yeni Kulüp',bulk:[['yillikPlanTarihi','Yıllık Plan Son Tarihi'],['toplumHizmetiTarihi','Toplum Hizmeti Planı Son Tarihi']],report:true},
 belirliGunler:{route:'Belirli Günler ve Haftalar',title:'Belirli Gün ve Haftalar',sub:'Görev dağılım çizelgesi',add:'+ Yeni Etkinlik',report:true},
 zumre:{route:'Zümre',title:'Zümre Toplantıları',sub:'Zümre toplantı takip çizelgesi',add:'+ Yeni Zümre',bulk:[['tarih1','1. Dönem Son Tarihi'],['tarih2','2. Dönem Son Tarihi'],['tarih3','Yıl Sonu Son Tarihi']],report:true},
 sok:{route:'ŞÖK',title:'ŞÖK – Şube Öğretmenler Kurulu',sub:'Şube öğretmenler kurulu toplantı takip çizelgesi',add:'+ Yeni ŞÖK',bulk:[['tarih1','1. Dönem Son Tarihi'],['tarih2','2. Dönem Son Tarihi'],['tarih3','Yıl Sonu Son Tarihi']],report:true},
 bepPlani:{route:'BEP Planları',title:'Yıllık / BEP Planları',sub:'Öğretmen ve sınıf bazlı yıllık plan ve BEP takibi',add:'+ Yeni Plan',bulk:[['yillikDersPlaniTarihi','Yıllık Ders Planı Son Tarihi'],['bepPlaniTarihi','BEP Planı Son Tarihi']],report:true},
 rehberlik:{route:'Rehberlik',title:'Rehberlik',sub:'Sınıf danışmanı ve aylık rehberlik takibi',add:'+ Yeni Rehberlik',bulk:[['yillikPlanTarihi','Yıllık Çalışma Planı Son Tarihi']],report:true},
 maarifRapor:{route:'Maarif Model Raporları',title:'Maarif Model Aylık Raporlar',sub:'Ders ve sınıf bazlı aylık rapor takibi',add:'+ Yeni Rapor',report:true},
 digerEvrak:{route:'Diğer Evrak',title:'Diğer Evraklar',sub:'Veli toplantı tutanakları ve diğer belgeler — teslim alınca tikleyin',add:'+ Yeni Evrak',report:false}
};
let currentType='';
function canEdit(type){try{if(typeof global.duzenleyebilir==='function')return !!global.duzenleyebilir(type);return global.PermissionService?.can?.('tools.schedules','edit')!==false}catch(_){return false}}
function typeFromTitle(title){const n=norm(title);if(n.includes('sosyal'))return'sosyalKulupler';if(n.includes('belirli'))return'belirliGunler';if(n.includes('zumre'))return'zumre';if(n==='sok'||n.includes('sube ogretmen'))return'sok';if(n.includes('bep'))return'bepPlani';if(n.includes('rehber'))return'rehberlik';if(n.includes('maarif'))return'maarifRapor';if(n.includes('diger'))return'digerEvrak';return''}
function countText(){const el=$('#toolsCount');if(el)el.textContent=`${arr(currentType).length} kayıt`}
function pageHost(){return $('#toolsContent')}
function routeMarker(type){return `<h3 data-cizelge-route-label style="position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0">${esc(CFG[type].route)}</h3>`}
function actions(type){const c=CFG[type],editable=canEdit(type);return `<div class="ka-row ka-wrap" style="justify-content:flex-end">${c.report?'<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-cizelge-report>🖨️ Rapor</button>':''}<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-cizelge-excel ${editable?'':'disabled'}>⇪ Excel'den İçe Aktar</button>${c.bulk?`<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-cizelge-bulk ${editable?'':'disabled'}>📅 Tarihleri Toplu Ayarla</button>`:''}<button class="ka-btn ka-btn--sm" type="button" data-cizelge-add ${editable?'':'disabled'}>${esc(c.add)}</button></div>`}
function pageHead(type){const c=CFG[type];return `${routeMarker(type)}<div class="ka-row ka-row--between ka-wrap"><div class="ka-grow"><h2>${esc(c.title)}</h2><p class="ka-muted">${esc(c.sub)}</p></div>${actions(type)}</div>`}
function checkArray(type,row){const labels=CONTROLS[type]||[],a=Array.isArray(row?.kontroller)?[...row.kontroller]:[];while(a.length<labels.length)a.push(false);return a.slice(0,labels.length)}
function controlGrid(type,row){const labels=CONTROLS[type];if(!labels)return'';const a=checkArray(type,row),disabled=!canEdit(type);return `<div class="ka-row ka-wrap" style="gap:6px;margin-top:10px">${labels.map((label,i)=>`<label class="ka-row" style="gap:5px;border:1px solid var(--ka-border);border-radius:10px;padding:6px 8px;${a[i]?'background:var(--ka-success-soft,rgba(24,122,83,.08));':''}"><input type="checkbox" data-cizelge-check data-type="${type}" data-id="${esc(row.id)}" data-index="${i}" ${a[i]?'checked':''} ${disabled?'disabled':''}><span style="font-size:12px">${esc(label)}</span></label>`).join('')}</div>`}
function teacherBadges(ids){const a=Array.isArray(ids)?ids:[];return a.length?`<div class="ka-row ka-wrap" style="gap:5px">${a.map(id=>`<span class="ka-badge">${esc(teacherName(id))}</span>`).join('')}</div>`:'<span class="ka-muted">Öğretmen atanmadı</span>'}
function editButton(type,id){return canEdit(type)?`<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-cizelge-edit="${esc(id)}">Düzenle</button>`:''}
function studentName(v){return String(v?.ogrenciAdi||[v?.ad,v?.soyad].filter(Boolean).join(' ')||'Öğrenci').trim()}
function clubStudents(id){return arr('veliler').filter(v=>String(v.kulupId||'')===String(id||'')).slice().sort((a,b)=>className(a.sinifId).localeCompare(className(b.sinifId),'tr',{numeric:true})||studentName(a).localeCompare(studentName(b),'tr'))}
function canManageClubStudents(r){try{const u=global.AKTIF_KULLANICI||global.AppStore?.get?.('session.user')||{};if(u.admin===true)return true;if(global.SiniflarService?._yetkiKontrolSessiz?.())return true;if(global.PermissionService?.can?.('people.students.edit','edit')===true||global.PermissionService?.can?.('people.classes','edit')===true)return true;if(typeof global.duzenleyebilir==='function'&&(global.duzenleyebilir('ogrenciler')||global.duzenleyebilir('siniflar')))return true;const tid=global.ToolsData?.teacherId?.()||u.bagliOgretmenId||u.ogretmenId||'';return !!(tid&&Array.isArray(r?.ogretmenIdler)&&r.ogretmenIdler.map(String).includes(String(tid)))}catch(_){return false}}
function socialCard(r){const a=checkArray('sosyalKulupler',r),done=a.filter(Boolean).length,classes=Array.isArray(r.sinifIdler)&&r.sinifIdler.length?r.sinifIdler.map(className).join(', '):'Sınıf kısıtı yok — tüm sınıflar seçebilir',students=clubStudents(r.id),manage=canManageClubStudents(r);return `<article class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><div class="ka-grow"><div class="ka-row ka-wrap"><strong>${esc(r.ad||'İsimsiz Kulüp')}</strong><span class="ka-badge">${r.aktif===false?'Pasif':'Aktif'}</span></div></div><div class="ka-row"><span class="ka-badge">${done}/12</span>${editButton('sosyalKulupler',r.id)}</div></div>${teacherBadges(r.ogretmenIdler)}<div class="ka-muted">${esc(classes)}</div>${r.yillikPlanTarihi||r.toplumHizmetiTarihi?`<div class="ka-muted">${r.yillikPlanTarihi?`Yıllık plan: ${esc(trDate(r.yillikPlanTarihi))}`:''}${r.yillikPlanTarihi&&r.toplumHizmetiTarihi?' · ':''}${r.toplumHizmetiTarihi?`Toplum hizmeti: ${esc(trDate(r.toplumHizmetiTarihi))}`:''}</div>`:''}<div class="ka-row ka-wrap">${manage?`<button class="ka-btn ka-btn--sm" type="button" data-club-student-edit="${esc(r.id)}">➕ Öğrenci Ekle</button>`:''}<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-club-student-list="${esc(r.id)}">👥 Öğrenciler (${students.length})</button></div>${controlGrid('sosyalKulupler',r)}</div></article>`}
function belirliCard(r){const done=checkArray('belirliGunler',r)[0];return `<article class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><div class="ka-grow"><strong>${esc(r.ad||'Etkinlik')}</strong><div class="ka-muted">${esc(trDate(r.tarihBaslangic))}${r.tarihBitis?' – '+esc(trDate(r.tarihBitis)):''}${Array.isArray(r.ogretmenIdler)&&r.ogretmenIdler.length?' · '+esc(r.ogretmenIdler.map(teacherName).join(', ')):''}</div></div><div class="ka-row"><span class="ka-badge">${done?'✓ Yapıldı':'Bekliyor'}</span>${editButton('belirliGunler',r.id)}</div></div>${r.aciklama?`<div class="ka-muted">${esc(r.aciklama)}</div>`:''}${controlGrid('belirliGunler',r)}</div></article>`}
function genericTitle(type,r){if(type==='zumre')return `${r.brans||'Zümre'}${r.sinif?' · '+r.sinif:''}`;if(type==='sok')return `${r.sinif||'ŞÖK'}${r.konu?' · '+r.konu:''}`;if(type==='bepPlani')return `${r.brans||'Yıllık / BEP'}${r.sinif?' · '+r.sinif:''}`;if(type==='rehberlik')return r.sinif||'Rehberlik';return'Kayıt'}
function genericMeta(type,r,includeTeacher=true){const dates=type==='bepPlani'?[r.yillikDersPlaniTarihi,r.bepPlaniTarihi]:type==='rehberlik'?[r.yillikPlanTarihi]:[r.tarih1,r.tarih2,r.tarih3];return [includeTeacher&&r.ogretmenId?teacherName(r.ogretmenId):'',...dates.filter(Boolean).map(trDate),r.aciklama||''].filter(Boolean).join(' · ')}
function genericCard(type,r,includeTeacher=true){const a=checkArray(type,r),done=a.filter(Boolean).length;return `<article class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><div class="ka-grow"><strong>${esc(genericTitle(type,r))}</strong><div class="ka-muted">${esc(genericMeta(type,r,includeTeacher))}</div></div><div class="ka-row"><span class="ka-badge">${done}/${a.length}</span>${editButton(type,r.id)}</div></div>${controlGrid(type,r)}</div></article>`}
const TEACHER_GROUPED_TYPES=new Set(['zumre','sok','bepPlani','rehberlik']);
function teacherGroupedList(type,rows){const labels=CONTROLS[type]||[],groups=new Map;rows.forEach(r=>{const key=r.ogretmenId?String(r.ogretmenId):'__yok__';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)});const name=key=>key==='__yok__'?'Öğretmen Atanmamış':teacherName(key)||'Öğretmen';return `<div class="ka-stack">${[...groups.entries()].sort((a,b)=>name(a[0]).localeCompare(name(b[0]),'tr')).map(([teacherId,records])=>{const sorted=records.slice().sort((a,b)=>genericTitle(type,a).localeCompare(genericTitle(type,b),'tr',{numeric:true})),done=sorted.reduce((sum,r)=>sum+checkArray(type,r).filter(Boolean).length,0),total=sorted.length*labels.length;return `<section class="ka-stack" data-cizelge-teacher-group="${esc(teacherId)}"><div class="ka-row ka-row--between ka-wrap" style="padding:8px 2px;border-bottom:1px solid var(--ka-border)"><div class="ka-grow"><strong>${esc(name(teacherId))}</strong><div class="ka-muted">${sorted.length} kayıt</div></div><span class="ka-badge">${done}/${total}</span></div><div class="ka-stack">${sorted.map(r=>genericCard(type,r,false)).join('')}</div></section>`}).join('')}</div>`}
function maarifCard(r){const a=checkArray('maarifRapor',r),done=a.filter(Boolean).length;return `<article class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><div class="ka-grow"><strong>${esc(r.ders||'Ders')} · ${esc(r.sinif||'Sınıf')}</strong><div class="ka-muted">${esc(teacherName(r.ogretmenId))}${r.aciklama?' · '+esc(r.aciklama):''}</div></div><div class="ka-row"><span class="ka-badge">${done}/10</span>${editButton('maarifRapor',r.id)}</div></div>${controlGrid('maarifRapor',r)}</div></article>`}
function maarifMatrix(rows){const labels=CONTROLS.maarifRapor||[],groups=new Map;rows.forEach(r=>{if(!r.ogretmenId)return;const key=String(r.ogretmenId);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)});if(!groups.size)return'<div class="ka-empty">Öğretmen atanmış kayıt yok.</div>';const disabled=!canEdit('maarifRapor');return `<div class="ka-stack">${[...groups.entries()].sort((a,b)=>teacherName(a[0]).localeCompare(teacherName(b[0]),'tr')).map(([teacherId,records])=>{const sorted=records.slice().sort((a,b)=>String(a.ders||'').localeCompare(String(b.ders||''),'tr')||String(a.sinif||'').localeCompare(String(b.sinif||''),'tr',{numeric:true})),done=sorted.reduce((sum,r)=>sum+checkArray('maarifRapor',r).filter(Boolean).length,0),total=sorted.length*labels.length,body=sorted.map(r=>{const checks=checkArray('maarifRapor',r);return `<tr><td><strong>${esc(r.ders||'Ders')}</strong><div class="ka-muted">${esc(r.sinif||'Sınıf')}${r.aciklama?' · '+esc(r.aciklama):''}</div></td>${labels.map((label,i)=>`<td style="text-align:center"><input type="checkbox" aria-label="${esc(label)}" data-cizelge-check data-type="maarifRapor" data-id="${esc(r.id)}" data-index="${i}" ${checks[i]?'checked':''} ${disabled?'disabled':''}></td>`).join('')}<td>${editButton('maarifRapor',r.id)}</td></tr>`}).join('');return `<section class="ka-card"><div class="ka-card__header ka-row ka-row--between"><div class="ka-grow"><strong>${esc(teacherName(teacherId)||'Öğretmen')}</strong><div class="ka-muted">${sorted.length} ders / sınıf kaydı</div></div><span class="ka-badge">${done}/${total}</span></div><div class="ka-card__body" style="padding:0"><div class="ka-table-wrap" style="border:0;border-radius:0 0 var(--ka-radius-lg) var(--ka-radius-lg)"><table class="ka-table" style="min-width:980px"><thead><tr><th>DERS / SINIF</th>${labels.map(label=>`<th style="text-align:center">${esc(label)}</th>`).join('')}<th>İŞLEM</th></tr></thead><tbody>${body}</tbody></table></div></div></section>`}).join('')}</div>`}
function otherCard(r){return `<article class="ka-card"><div class="ka-card__body"><div class="ka-row ka-row--between"><div class="ka-grow"><strong>${esc(r.evrakAdi||'—')}</strong><div class="ka-muted">${[r.tur,r.sinif,r.tarih?trDate(r.tarih):'',r.aciklama].filter(Boolean).map(esc).join(' · ')}</div></div><div class="ka-row"><span class="ka-badge">${r.teslimEdildi?'✓ Teslim':'Bekliyor'}</span>${editButton('digerEvrak',r.id)}</div></div></div></article>`}
function bodyHtml(type){let rows=arr(type).slice();if(type==='belirliGunler')rows.sort((a,b)=>String(a.tarihBaslangic||'').localeCompare(String(b.tarihBaslangic||'')));else if(type==='digerEvrak')rows.sort((a,b)=>String(b.tarih||'').localeCompare(String(a.tarih||'')));else rows.sort((a,b)=>genericTitle(type,a).localeCompare(genericTitle(type,b),'tr',{numeric:true}));if(!rows.length)return'<div class="ka-empty">Henüz kayıt eklenmedi.</div>';if(type==='sosyalKulupler')return `<div class="ka-grid">${rows.map(socialCard).join('')}</div>`;if(type==='belirliGunler')return `<div class="ka-stack">${rows.map(belirliCard).join('')}</div>`;if(type==='maarifRapor')return maarifMatrix(rows);if(type==='digerEvrak')return `<div class="ka-stack">${rows.map(otherCard).join('')}</div>`;if(TEACHER_GROUPED_TYPES.has(type))return teacherGroupedList(type,rows);return `<div class="ka-stack">${rows.map(r=>genericCard(type,r)).join('')}</div>`}
function render(force=false){if(!currentType||!CFG[currentType])return false;const host=pageHost();if(!host)return false;const sig=JSON.stringify([currentType,arr(currentType).map(r=>[r.id,r.ad,r.evrakAdi,r.konu,r.brans,r.sinif,r.ogretmenId,r.ogretmenIdler,r.kontroller,r.aktif,r.tarih,r.tarih1,r.tarih2,r.tarih3,r.yillikPlanTarihi,r.toplumHizmetiTarihi,r.yillikDersPlaniTarihi,r.bepPlaniTarihi,r.teslimEdildi,r.aciklama])]);if(!force&&host.dataset.classicCizelgeSignature===sig&&host.querySelector(`[data-classic-cizelge-page="${currentType}"]`))return true;host.dataset.classicCizelgeSignature=sig;host.innerHTML=`<section class="ka-stack" data-classic-cizelge-page="${currentType}" style="position:relative">${pageHead(currentType)}${bodyHtml(currentType)}</section>`;countText();bindPage(host);global.PermissionService?.apply?.(host);return true}
function bindPage(root){root.querySelector('[data-cizelge-add]')?.addEventListener('click',()=>openEdit(currentType));root.querySelectorAll('[data-cizelge-edit]').forEach(b=>b.addEventListener('click',()=>openEdit(currentType,b.dataset.cizelgeEdit)));root.querySelectorAll('[data-cizelge-check]').forEach(cb=>cb.addEventListener('change',()=>toggleControl(cb)));root.querySelector('[data-cizelge-bulk]')?.addEventListener('click',()=>openBulk(currentType));root.querySelector('[data-cizelge-report]')?.addEventListener('click',()=>printReport(currentType));root.querySelector('[data-cizelge-excel]')?.addEventListener('click',()=>chooseExcel(currentType));root.querySelectorAll('[data-club-student-edit]').forEach(b=>b.addEventListener('click',()=>openClubStudentEditor(b.dataset.clubStudentEdit)));root.querySelectorAll('[data-club-student-list]').forEach(b=>b.addEventListener('click',()=>openClubStudentList(b.dataset.clubStudentList)))}
async function toggleControl(cb){const type=cb.dataset.type,id=cb.dataset.id,index=Number(cb.dataset.index),row=arr(type).find(x=>x.id===id);if(!row)return;const values=checkArray(type,row);values[index]=cb.checked;cb.disabled=true;try{await global.CizelgelerService.kontrolToggle(type,id,values);row.kontroller=values;render(true)}catch(e){cb.checked=!cb.checked;global.toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'İşaretleme kaydedilemedi.')}finally{cb.disabled=false}}
function teachersChecks(name,selected=[]){const set=new Set(Array.isArray(selected)?selected:[]);return `<div class="ka-stack" style="max-height:210px;overflow:auto;border:1px solid var(--ka-border);border-radius:12px;padding:8px">${arr('ogretmenler').slice().sort((a,b)=>`${a.ad||''} ${a.soyad||''}`.localeCompare(`${b.ad||''} ${b.soyad||''}`,'tr')).map(o=>`<label class="ka-row"><input type="checkbox" name="${name}" value="${esc(o.id)}" ${set.has(o.id)?'checked':''}><span>${esc(`${o.ad||''} ${o.soyad||''}`.trim())}</span></label>`).join('')||'<span class="ka-muted">Öğretmen bulunamadı.</span>'}</div>`}
function teacherSelect(name,value=''){return `<select name="${name}" required><option value="">— Seçiniz —</option>${arr('ogretmenler').slice().sort((a,b)=>`${a.ad||''} ${a.soyad||''}`.localeCompare(`${b.ad||''} ${b.soyad||''}`,'tr')).map(o=>`<option value="${esc(o.id)}" ${o.id===value?'selected':''}>${esc(`${o.ad||''} ${o.soyad||''}`.trim())}</option>`).join('')}</select>`}
function classSelect(name,value='',optional=false){return `<select name="${name}" ${optional?'':'required'}><option value="">${optional?'— Seçiniz (opsiyonel) —':'— Seçiniz —'}</option>${arr('siniflar').slice().sort((a,b)=>String(a.ad||'').localeCompare(String(b.ad||''),'tr',{numeric:true})).map(s=>`<option value="${esc(s.ad||'')}" ${String(s.ad||'')===String(value||'')?'selected':''}>${esc(s.ad||'')}</option>`).join('')}</select>`}
function classChecks(name,selected=[],useId=false,quick=false){const set=new Set(Array.isArray(selected)?selected:[]),quickBar=quick?`<div class="ka-row ka-wrap" style="gap:6px"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-class-level-quick="primary">🧒 Tüm İlkokul (1-4)</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-class-level-quick="middle">🎓 Tüm Ortaokul (5-8)</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-class-level-quick="clear">✕ Temizle</button></div>`:'';return `${quickBar}<div class="ka-stack" style="max-height:190px;overflow:auto;border:1px solid var(--ka-border);border-radius:12px;padding:8px">${arr('siniflar').slice().sort((a,b)=>String(a.ad||'').localeCompare(String(b.ad||''),'tr',{numeric:true})).map(s=>{const v=useId?s.id:s.ad;return`<label class="ka-row"><input type="checkbox" name="${name}" value="${esc(v||'')}" data-seviye="${esc(s.seviye||'')}" ${set.has(v)?'checked':''}><span>${esc(s.ad||'')}</span></label>`}).join('')||'<span class="ka-muted">Sınıf bulunamadı.</span>'}</div>${quick?'<small class="ka-muted">Hiç sınıf seçilmezse bu kulübü tüm sınıflar seçebilir.</small>':''}`;}
function simpleSelect(name,value,list,optional=false){return `<select name="${name}" ${optional?'':'required'}><option value="">${optional?'— Seçiniz (opsiyonel) —':'— Seçiniz —'}</option>${list.map(v=>`<option value="${esc(v)}" ${String(v)===String(value||'')?'selected':''}>${esc(v)}</option>`).join('')}</select>`}
function branchSelect(value=''){const list=arr('bransListesi').map(x=>x.ad).filter(Boolean);return simpleSelect('brans',value,list,false)}
function lessonSelect(value=''){const list=arr('dersListesi').map(x=>x.ad).filter(Boolean);return simpleSelect('ders',value,list,false)}
const field=(label,input)=>`<label class="ka-field"><span class="ka-field__label">${label}</span>${input}</label>`;
function formBody(type,r){if(type==='sosyalKulupler')return `${field('Kulüp Adı',`<input name="ad" value="${esc(r.ad||'')}" required>`)}${field('Danışman Öğretmenler',teachersChecks('ogretmenIdler',r.ogretmenIdler))}${field('Bu Kulübü Seçebilecek Sınıflar',classChecks('sinifIdler',r.sinifIdler,true,true))}<div class="ka-grid">${field('Yıllık Plan Son Tarihi (opsiyonel)',`<input type="date" name="yillikPlanTarihi" value="${esc(r.yillikPlanTarihi||'')}">`)}${field('Toplum Hizmeti Planı Son Tarihi (opsiyonel)',`<input type="date" name="toplumHizmetiTarihi" value="${esc(r.toplumHizmetiTarihi||'')}">`)}</div><label class="ka-row"><input type="checkbox" name="aktif" ${r.id?r.aktif!==false?'checked':'':'checked'}><span>Aktif Kulüp</span></label>`;
if(type==='belirliGunler')return `${field('Etkinlik Adı',`<input name="ad" value="${esc(r.ad||'')}" required>`)}<div class="ka-grid">${field('Başlangıç Tarihi',`<input type="date" name="tarihBaslangic" value="${esc(r.tarihBaslangic||today())}" required>`)}${field('Bitiş Tarihi (opsiyonel)',`<input type="date" name="tarihBitis" value="${esc(r.tarihBitis||'')}">`)}</div>${field('Sorumlu Öğretmenler',teachersChecks('ogretmenIdler',r.ogretmenIdler))}${field('Notlar',`<textarea name="aciklama" rows="3">${esc(r.aciklama||'')}</textarea>`)}`;
if(type==='zumre')return `${field('Öğretmen',teacherSelect('ogretmenId',r.ogretmenId))}${field('Branş / Ders',branchSelect(r.brans))}${field('Sınıf (opsiyonel)',classSelect('sinif',r.sinif,true))}<div class="ka-grid">${['tarih1','tarih2','tarih3'].map((k,i)=>field(['1. Dönem Son Tarihi','2. Dönem Son Tarihi','Yıl Sonu Son Tarihi'][i]+ ' (opsiyonel)',`<input type="date" name="${k}" value="${esc(r[k]||'')}">`)).join('')}</div>${field('Notlar',`<textarea name="aciklama" rows="3">${esc(r.aciklama||'')}</textarea>`)}`;
if(type==='sok')return `${field('Öğretmen',teacherSelect('ogretmenId',r.ogretmenId))}${field('Sınıf',classSelect('sinif',r.sinif,false))}${field('Konu',`<input name="konu" value="${esc(r.konu||'')}" required>`)}<div class="ka-grid">${['tarih1','tarih2','tarih3'].map((k,i)=>field(['1. Dönem Son Tarihi','2. Dönem Son Tarihi','Yıl Sonu Son Tarihi'][i]+' (opsiyonel)',`<input type="date" name="${k}" value="${esc(r[k]||'')}">`)).join('')}</div>${field('Notlar',`<textarea name="aciklama" rows="3">${esc(r.aciklama||'')}</textarea>`)}`;
if(type==='bepPlani')return `${field('Öğretmen',teacherSelect('ogretmenId',r.ogretmenId))}${field('Branş',branchSelect(r.brans))}${field(r.id?'Sınıf':'Sınıflar (opsiyonel — her sınıf ayrı kayıt)',r.id?classSelect('sinif',r.sinif,true):classChecks('siniflar',[],false))}<div class="ka-grid">${field('Yıllık Ders Planı Son Tarihi (opsiyonel)',`<input type="date" name="yillikDersPlaniTarihi" value="${esc(r.yillikDersPlaniTarihi||'')}">`)}${field('BEP Planı Son Tarihi (opsiyonel)',`<input type="date" name="bepPlaniTarihi" value="${esc(r.bepPlaniTarihi||'')}">`)}</div>${field('Notlar',`<textarea name="aciklama" rows="3">${esc(r.aciklama||'')}</textarea>`)}`;
if(type==='rehberlik')return `${field('Öğretmen',teacherSelect('ogretmenId',r.ogretmenId))}${field('Sınıf',classSelect('sinif',r.sinif,false))}${field('Yıllık Çalışma Planı Son Tarihi (opsiyonel)',`<input type="date" name="yillikPlanTarihi" value="${esc(r.yillikPlanTarihi||'')}">`)}${field('Notlar',`<textarea name="aciklama" rows="3">${esc(r.aciklama||'')}</textarea>`)}`;
if(type==='maarifRapor')return `${field('Öğretmen',teacherSelect('ogretmenId',r.ogretmenId))}${field('Ders',lessonSelect(r.ders))}${field(r.id?'Sınıf':'Sınıflar (çoklu seçim — her sınıf ayrı kayıt olur)',r.id?classSelect('sinif',r.sinif,false):classChecks('siniflar',[],false))}${field('Açıklama (opsiyonel)',`<textarea name="aciklama" rows="3">${esc(r.aciklama||'')}</textarea>`)}`;
if(type==='digerEvrak'){const types=['Veli Toplantı Tutanağı','Zümre Tutanağı','Kurul Kararı','Dilekçe','Rapor','Diğer'];return `${field('Evrak Adı',`<input name="evrakAdi" value="${esc(r.evrakAdi||'')}" placeholder="örn: Veli Toplantı Tutanağı - 1A" required>`)}${field('Tür',simpleSelect('tur',r.tur||types[0],types,false))}${field('Sınıf (opsiyonel)',classSelect('sinif',r.sinif,true))}${field('Tarih (opsiyonel)',`<input type="date" name="tarih" value="${esc(r.tarih||'')}">`)}${field('Açıklama',`<textarea name="aciklama" rows="3">${esc(r.aciklama||'')}</textarea>`)}<label class="ka-row"><input type="checkbox" name="teslimEdildi" ${r.teslimEdildi?'checked':''}><span>Teslim Edildi</span></label>`}return''}
function bindClassQuickSelect(modal){modal?.querySelectorAll('[data-class-level-quick]').forEach(button=>button.addEventListener('click',()=>{const mode=button.dataset.classLevelQuick;modal.querySelectorAll('input[name="sinifIdler"][data-seviye]').forEach(cb=>{if(mode==='clear'){cb.checked=false;return}const level=Number(cb.dataset.seviye);if(!Number.isFinite(level))return;if(mode==='primary'&&level>=1&&level<=4)cb.checked=true;if(mode==='middle'&&level>=5&&level<=8)cb.checked=true})}))}
function openEdit(type,id=''){const row=id?arr(type).find(x=>x.id===id)||{}:{};const c=CFG[type];closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="ka-modal-backdrop" data-cizelge-modal style="z-index:1400"><form class="ka-modal" data-cizelge-form data-type="${type}" data-id="${esc(id)}"><div class="ka-modal__header"><h2>${esc(id?c.title+' — Düzenle':c.add.replace(/^\+\s*/,''))}</h2></div><div class="ka-modal__body ka-stack">${formBody(type,row)}</div><div class="ka-modal__footer">${id?'<button class="ka-btn ka-btn--danger" type="button" data-cizelge-delete>Sil</button>':''}<span class="ka-grow"></span><button class="ka-btn ka-btn--secondary" type="button" data-cizelge-cancel>Vazgeç</button><button class="ka-btn" type="submit">Kaydet</button></div></form></div>`);const modal=$('[data-cizelge-modal]');bindClassQuickSelect(modal);modal?.addEventListener('click',e=>{if(e.target===modal)closeModal()});modal?.querySelector('[data-cizelge-cancel]')?.addEventListener('click',closeModal);modal?.querySelector('[data-cizelge-delete]')?.addEventListener('click',()=>deleteRow(type,id));modal?.querySelector('[data-cizelge-form]')?.addEventListener('submit',saveForm)}
function closeModal(){document.querySelector('[data-cizelge-modal]')?.remove()}
async function prepareClubStudentData(){if(!global.ToolsData?.prepareClubStudents)throw new Error('Kulüp öğrenci verisi hazırlanamadı.');await global.ToolsData.prepareClubStudents()}
async function ensureClubStudentService(){await prepareClubStudentData();if(!global.SiniflarService?.ogrenciKulupGuncelle){if(!global.AppLoader?.loadScript)throw new Error('Öğrenci servisi yüklenemedi.');await global.AppLoader.loadScript('js/modules/people.js')}if(!global.SiniflarService?.ogrenciKulupGuncelle)throw new Error('Öğrenci servisi hazır değil.');return global.SiniflarService}
function allowedClubClasses(club){const ids=Array.isArray(club?.sinifIdler)?new Set(club.sinifIdler.map(String)):new Set();return arr('siniflar').filter(s=>!ids.size||ids.has(String(s.id))).slice().sort((a,b)=>String(a.ad||'').localeCompare(String(b.ad||''),'tr',{numeric:true}))}
function studentsInClass(id){return arr('veliler').filter(v=>String(v.sinifId||'')===String(id||'')).slice().sort((a,b)=>{const an=Number(a.ogrenciNo||a.no||0),bn=Number(b.ogrenciNo||b.no||0);return(an&&bn?an-bn:0)||studentName(a).localeCompare(studentName(b),'tr')})}
async function openClubStudentEditor(id){try{const club=arr('sosyalKulupler').find(x=>String(x.id)===String(id));if(!club)throw new Error('Kulüp bulunamadı.');if(!canManageClubStudents(club)){global.toast?.('Bu kulübün öğrenci listesini düzenleme yetkiniz yok.');return}await ensureClubStudentService();const current=new Set(clubStudents(id).map(v=>String(v.id))),groups=allowedClubClasses(club).map(s=>{const students=studentsInClass(s.id),selected=students.filter(v=>current.has(String(v.id))).length;return `<details class="ka-card" ${selected?'open':''}><summary><span class="ka-card__body ka-row ka-row--between"><strong>${esc(className(s.id))}</strong><span class="ka-badge">${students.length} öğrenci${selected?` · ${selected} seçili`:''}</span></span></summary><div class="ka-card__body ka-stack">${students.length?students.map(v=>{const other=v.kulupId&&String(v.kulupId)!==String(id)?(v.kulupAdi||arr('sosyalKulupler').find(k=>String(k.id)===String(v.kulupId))?.ad||'Başka kulüp'):'';return `<label class="ka-row"><input type="checkbox" name="studentIds" value="${esc(v.id)}" ${current.has(String(v.id))?'checked':''}><span class="ka-stack ka-grow"><strong>${esc(studentName(v))}</strong><small class="ka-muted">${v.ogrenciNo?`No ${esc(v.ogrenciNo)}`:'Öğrenci no yok'}${other?` · ${esc(other)} kulübünde`:''}</small></span></label>`}).join(''):'<div class="ka-muted">Bu sınıfta öğrenci yok.</div>'}</div></details>`}).join('');closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="ka-modal-backdrop" data-cizelge-modal><form class="ka-modal" data-club-student-form data-club-id="${esc(id)}"><div class="ka-modal__header"><h2>${esc(club.ad||'Sosyal Kulüp')} — Öğrenci Ekle</h2></div><div class="ka-modal__body ka-stack"><p class="ka-muted">Kulübe dahil olacak öğrencileri işaretleyin. Başka bir kulüpte görünen öğrenci seçilirse bu kulübe taşınır.</p>${groups||'<div class="ka-empty">Bu kulüp için seçilebilir sınıf bulunamadı.</div>'}</div><div class="ka-modal__footer"><button class="ka-btn ka-btn--secondary" type="button" data-cizelge-cancel>Vazgeç</button><button class="ka-btn" type="submit">Kaydet</button></div></form></div>`);const modal=$('[data-cizelge-modal]');modal?.addEventListener('click',e=>{if(e.target===modal)closeModal()});modal?.querySelector('[data-cizelge-cancel]')?.addEventListener('click',closeModal);modal?.querySelector('[data-club-student-form]')?.addEventListener('submit',saveClubStudentAssignments)}catch(e){global.toast?.('Öğrenci listesi açılamadı: '+(e?.message||e))}}
async function saveClubStudentAssignments(e){e.preventDefault();const f=e.currentTarget,id=f.dataset.clubId||'',club=arr('sosyalKulupler').find(x=>String(x.id)===String(id));if(!club)return;const before=new Set(clubStudents(id).map(v=>String(v.id))),after=new Set(new FormData(f).getAll('studentIds').map(String)),added=[...after].filter(x=>!before.has(x)),removed=[...before].filter(x=>!after.has(x)),submit=f.querySelector('[type="submit"]');if(!added.length&&!removed.length){global.toast?.('Değişiklik yapılmadı.');closeModal();return}try{submit.disabled=true;const service=await ensureClubStudentService();for(const studentId of added)await service.ogrenciKulupGuncelle(studentId,id,club.ad||'');for(const studentId of removed)await service.ogrenciKulupGuncelle(studentId,'','');global.toast?.(`Kaydedildi — ${added.length} eklendi, ${removed.length} çıkarıldı.`);closeModal();render(true)}catch(err){global.toast?.(err?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Kulüp öğrenci listesi kaydedilemedi.');render(true)}finally{if(submit?.isConnected)submit.disabled=false}}
async function openClubStudentList(id){try{await prepareClubStudentData();const club=arr('sosyalKulupler').find(x=>String(x.id)===String(id));if(!club)throw new Error('Kulüp bulunamadı.');const students=clubStudents(id);closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="ka-modal-backdrop" data-cizelge-modal><section class="ka-modal"><div class="ka-modal__header"><h2>${esc(club.ad||'Sosyal Kulüp')} — Öğrenciler</h2></div><div class="ka-modal__body ka-stack"><div class="ka-row ka-row--between"><span class="ka-muted">${esc((club.ogretmenIdler||[]).map(teacherName).join(', ')||'Danışman öğretmen atanmadı')}</span><span class="ka-badge">${students.length} öğrenci</span></div>${students.length?students.map((v,i)=>`<article class="ka-card"><div class="ka-card__body ka-row"><span class="ka-badge">${i+1}</span><div class="ka-grow"><strong>${esc(studentName(v))}</strong><div class="ka-muted">${esc(className(v.sinifId))}${v.ogrenciNo?' · No '+esc(v.ogrenciNo):''}</div></div></div></article>`).join(''):'<div class="ka-empty">Bu kulübe atanmış öğrenci yok.</div>'}</div><div class="ka-modal__footer"><button class="ka-btn ka-btn--secondary" type="button" data-cizelge-cancel>Kapat</button><button class="ka-btn" type="button" data-club-student-print>🖨 Öğrenci Listesi</button></div></section></div>`);const modal=$('[data-cizelge-modal]');modal?.addEventListener('click',e=>{if(e.target===modal)closeModal()});modal?.querySelector('[data-cizelge-cancel]')?.addEventListener('click',closeModal);modal?.querySelector('[data-club-student-print]')?.addEventListener('click',()=>printClubStudentList(id))}catch(e){global.toast?.('Öğrenci listesi açılamadı: '+(e?.message||e))}}
async function printClubStudentList(id){try{await prepareClubStudentData();const club=arr('sosyalKulupler').find(x=>String(x.id)===String(id));if(!club)throw new Error('Kulüp bulunamadı.');const students=clubStudents(id),advisers=(club.ogretmenIdler||[]).map(teacherName).filter(Boolean).join(', ')||'—',body=`<p><b>Danışman Öğretmenler:</b> ${esc(advisers)}</p><table><thead><tr><th>No</th><th>Öğrenci</th><th>Sınıf</th><th>Öğrenci No</th></tr></thead><tbody>${students.length?students.map((v,i)=>`<tr><td>${i+1}</td><td>${esc(studentName(v))}</td><td>${esc(className(v.sinifId))}</td><td>${esc(v.ogrenciNo||'—')}</td></tr>`).join(''):'<tr><td colspan="4">Bu kulübe atanmış öğrenci yok.</td></tr>'}</tbody></table>`;await ensureReport();await global.ReportEngine.printReport(`${club.ad||'Sosyal Kulüp'} — Öğrenci Listesi`,body,{yon:'dikey',compact:true,fileName:`${club.ad||'Sosyal Kulüp'} Öğrenci Listesi`,ustBaslik:'Sosyal Kulüpler'})}catch(e){global.toast?.('Rapor açılamadı: '+(e?.message||e))}}
function getAll(fd,name){return fd.getAll(name).map(v=>String(v)).filter(Boolean)}
async function saveForm(e){e.preventDefault();const f=e.currentTarget,type=f.dataset.type,id=f.dataset.id||'',fd=new FormData(f),row=id?arr(type).find(x=>x.id===id):null;let v={};if(type==='sosyalKulupler')v={ad:String(fd.get('ad')||'').trim(),ogretmenIdler:getAll(fd,'ogretmenIdler'),sinifIdler:getAll(fd,'sinifIdler'),yillikPlanTarihi:String(fd.get('yillikPlanTarihi')||'')||null,toplumHizmetiTarihi:String(fd.get('toplumHizmetiTarihi')||'')||null,aktif:fd.has('aktif'),kontroller:row?.kontroller||Array(12).fill(false)};else if(type==='belirliGunler')v={ad:String(fd.get('ad')||'').trim(),tarihBaslangic:String(fd.get('tarihBaslangic')||''),tarihBitis:String(fd.get('tarihBitis')||''),ogretmenIdler:getAll(fd,'ogretmenIdler'),aciklama:String(fd.get('aciklama')||'').trim(),kontroller:row?.kontroller||[false]};else if(type==='zumre')v={ogretmenId:String(fd.get('ogretmenId')||''),brans:String(fd.get('brans')||''),sinif:String(fd.get('sinif')||''),tarih1:String(fd.get('tarih1')||''),tarih2:String(fd.get('tarih2')||''),tarih3:String(fd.get('tarih3')||''),aciklama:String(fd.get('aciklama')||'').trim(),kontroller:row?.kontroller||[false,false,false]};else if(type==='sok')v={ogretmenId:String(fd.get('ogretmenId')||''),sinif:String(fd.get('sinif')||''),konu:String(fd.get('konu')||'').trim(),tarih1:String(fd.get('tarih1')||''),tarih2:String(fd.get('tarih2')||''),tarih3:String(fd.get('tarih3')||''),aciklama:String(fd.get('aciklama')||'').trim(),kontroller:row?.kontroller||[false,false,false]};else if(type==='bepPlani')v={ogretmenId:String(fd.get('ogretmenId')||''),brans:String(fd.get('brans')||''),sinif:String(fd.get('sinif')||''),yillikDersPlaniTarihi:String(fd.get('yillikDersPlaniTarihi')||'')||null,bepPlaniTarihi:String(fd.get('bepPlaniTarihi')||'')||null,aciklama:String(fd.get('aciklama')||'').trim(),kontroller:row?.kontroller||[false,false]};else if(type==='rehberlik')v={ogretmenId:String(fd.get('ogretmenId')||''),sinif:String(fd.get('sinif')||''),yillikPlanTarihi:String(fd.get('yillikPlanTarihi')||'')||null,aciklama:String(fd.get('aciklama')||'').trim(),kontroller:row?.kontroller||Array(12).fill(false)};else if(type==='maarifRapor')v={ogretmenId:String(fd.get('ogretmenId')||''),ders:String(fd.get('ders')||''),sinif:String(fd.get('sinif')||''),aciklama:String(fd.get('aciklama')||'').trim(),kontroller:row?.kontroller||Array(10).fill(false)};else if(type==='digerEvrak')v={evrakAdi:String(fd.get('evrakAdi')||'').trim(),tur:String(fd.get('tur')||''),sinif:String(fd.get('sinif')||''),tarih:String(fd.get('tarih')||''),aciklama:String(fd.get('aciklama')||'').trim(),teslimEdildi:fd.has('teslimEdildi')};try{const submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;if(!id&&(type==='bepPlani'||type==='maarifRapor')){const classes=getAll(fd,'siniflar');if(type==='maarifRapor'&&!classes.length)throw new Error('En az bir sınıf seçiniz.');if(classes.length){const base={...v};delete base.sinif;await global.CizelgelerService.cokluKayitOlustur(type,base,'sinif',classes)}else await global.CizelgelerService.kayitKaydet(type,null,{...v,sinif:''})}else await global.CizelgelerService.kayitKaydet(type,id||null,v);global.toast?.('Kaydedildi.');closeModal();render(true)}catch(err){global.toast?.(err?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':(err?.message||'Kaydedilemedi.'))}finally{const submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=false}}
async function deleteRow(type,id){if(!id||!confirm('Bu kaydı silmek istiyor musunuz?'))return;try{await global.CizelgelerService.kayitSil(type,id);global.toast?.('Kayıt silindi.');closeModal();render(true)}catch(e){global.toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Kayıt silinemedi.')}}
function recordLabel(type,r){if(type==='sosyalKulupler')return r.ad||'Kulüp';if(type==='belirliGunler')return r.ad||'Etkinlik';if(type==='digerEvrak')return r.evrakAdi||'Evrak';return `${teacherName(r.ogretmenId)} — ${genericTitle(type,r)}`}
function reportRecordLabel(type,r){if(type==='sosyalKulupler'){const teachers=Array.isArray(r.ogretmenIdler)?r.ogretmenIdler.map(teacherName).filter(Boolean).join(', '):'',classes=Array.isArray(r.sinifIdler)&&r.sinifIdler.length?r.sinifIdler.map(className).join(', '):'Tüm sınıflar';return [r.ad||'Kulüp',r.aktif===false?'Pasif':'Aktif',teachers?`Danışman: ${teachers}`:'Öğretmen atanmadı',`Sınıflar: ${classes}`,r.yillikPlanTarihi?`Yıllık plan: ${trDate(r.yillikPlanTarihi)}`:'',r.toplumHizmetiTarihi?`Toplum hizmeti: ${trDate(r.toplumHizmetiTarihi)}`:''].filter(Boolean).join(' · ')}if(type==='maarifRapor')return [r.ders||'Ders',r.sinif||'Sınıf',r.aciklama||''].filter(Boolean).join(' · ');return [genericTitle(type,r),genericMeta(type,r,false)].filter(Boolean).join(' · ')}
function openBulk(type){const c=CFG[type],rows=arr(type);if(!c?.bulk)return;if(!rows.length){global.toast?.('Bu türde henüz kayıt yok.');return}closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="ka-modal-backdrop" data-cizelge-modal style="z-index:1400"><form class="ka-modal" data-cizelge-bulk-form data-type="${type}"><div class="ka-modal__header"><h2>📅 Tarihleri Toplu Ayarla</h2></div><div class="ka-modal__body ka-stack"><p class="ka-muted">Dolu bıraktığınız tarihler seçili kayıtların tamamına uygulanır. Boş alanlar mevcut değeri değiştirmez.</p><div class="ka-grid">${c.bulk.map(([k,l])=>field(esc(l),`<input type="date" name="${k}">`)).join('')}</div>${field('Kayıtlar',`<div class="ka-stack" style="max-height:260px;overflow:auto;border:1px solid var(--ka-border);border-radius:12px;padding:8px">${rows.map(r=>`<label class="ka-row"><input type="checkbox" name="ids" value="${esc(r.id)}" checked><span>${esc(recordLabel(type,r))}</span></label>`).join('')}</div>`)}</div><div class="ka-modal__footer"><button class="ka-btn ka-btn--secondary" type="button" data-cizelge-cancel>Vazgeç</button><button class="ka-btn" type="submit">Uygula</button></div></form></div>`);const modal=$('[data-cizelge-modal]');modal?.querySelector('[data-cizelge-cancel]')?.addEventListener('click',closeModal);modal?.addEventListener('click',e=>{if(e.target===modal)closeModal()});modal?.querySelector('[data-cizelge-bulk-form]')?.addEventListener('submit',saveBulk)}
async function saveBulk(e){e.preventDefault();const f=e.currentTarget,type=f.dataset.type,c=CFG[type],fd=new FormData(f),ids=getAll(fd,'ids'),patch={};for(const[k]of c.bulk){const v=String(fd.get(k)||'');if(v)patch[k]=v}if(!Object.keys(patch).length){global.toast?.('En az bir tarih girin.');return}if(!ids.length){global.toast?.('En az bir kayıt seçin.');return}try{const b=f.querySelector('[type="submit"]');b.disabled=true;await Promise.all(ids.map(id=>global.CizelgelerService.kayitKaydet(type,id,patch)));global.toast?.(`${ids.length} kayıt güncellendi.`);closeModal();render(true)}catch(err){global.toast?.(err?.message||'Toplu güncelleme yapılamadı.')}}
async function ensureReport(){if(global.ReportEngine)return true;if(!global.AppLoader?.loadScript)throw new Error('Rapor motoru yüklenemedi.');await global.AppLoader.loadScript('js/modules/report-engine.js');return!!global.ReportEngine}
function reportTable(type){const rows=arr(type),labels=CONTROLS[type]||[];if(type==='digerEvrak')return'';if(type==='belirliGunler'){const heads=['Etkinlik','Başlangıç','Bitiş','Sorumlu Öğretmenler','Durum','Notlar'],body=rows.map(r=>{const teachers=Array.isArray(r.ogretmenIdler)?r.ogretmenIdler.map(teacherName).filter(Boolean).join(', '):'',cells=[r.ad||'Etkinlik',trDate(r.tarihBaslangic),r.tarihBitis?trDate(r.tarihBitis):'',teachers,checkArray(type,r)[0]?'Yapıldı':'Bekliyor',r.aciklama||''];return `<tr>${cells.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`}).join('');return `<table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${heads.length}">Kayıt yok.</td></tr>`}</tbody></table>`}let heads=['Kayıt'];if(type!=='sosyalKulupler')heads.unshift('Öğretmen');heads.push(...labels);const body=rows.map(r=>{const first=reportRecordLabel(type,r),checks=checkArray(type,r).map(v=>v?'✓':'');const cells=[];if(type!=='sosyalKulupler')cells.push(teacherName(r.ogretmenId));cells.push(first,...checks);return `<tr>${cells.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`}).join('');return `<table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${heads.length}">Kayıt yok.</td></tr>`}</tbody></table>`}
async function printReport(type){try{await ensureReport();await global.ReportEngine.printReport(type==='maarifRapor'?'Maarif Model Aylık Raporlar Çizelgesi':CFG[type].title,reportTable(type),{yon:(CONTROLS[type]?.length||0)>5?'yatay':'dikey',compact:true,fileName:CFG[type].title})}catch(e){global.toast?.('Rapor açılamadı: '+(e?.message||e))}}
function loadScript(src,test){if(test())return Promise.resolve();return new Promise((ok,no)=>{const old=[...document.scripts].find(s=>s.src===src);if(old){old.addEventListener('load',ok,{once:true});old.addEventListener('error',no,{once:true});return}const s=document.createElement('script');s.src=src;s.onload=ok;s.onerror=no;document.head.appendChild(s)})}
const ensureXlsx=()=>loadScript('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js',()=>!!global.XLSX);
function normalizeHeader(v){return norm(v).replace(/\s+/g,' ')}
function excelDate(v){if(v instanceof Date&&!Number.isNaN(v.getTime()))return v.toISOString().slice(0,10);if(typeof v==='number'){const d=new Date(Math.round((v-25569)*86400*1000));return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,10)}const s=String(v??'').trim();if(/^\d{4}-\d{2}-\d{2}$/.test(s))return s;const m=s.match(/^(\d{1,2})[.\/]([0-9]{1,2})[.\/](\d{4})$/);return m?`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`:s}
function teacherIdByName(v){const n=norm(v);return arr('ogretmenler').find(o=>norm(`${o.ad||''} ${o.soyad||''}`)===n)?.id||''}
function teacherIdsByNames(v){return String(v||'').split(/[,;\n]/).map(x=>teacherIdByName(x)).filter(Boolean)}
function classIdsByNames(v){const names=String(v||'').split(/[,;\n]/).map(norm).filter(Boolean);return arr('siniflar').filter(s=>names.includes(norm(s.ad))).map(s=>s.id)}
function truth(v){return ['1','true','evet','aktif','x','✓','teslim','tamam'].includes(norm(v))}
function rowValue(obj,...keys){for(const k of keys){const wanted=normalizeHeader(k),found=Object.keys(obj).find(x=>normalizeHeader(x)===wanted);if(found!==undefined&&obj[found]!==null&&obj[found]!==undefined)return obj[found]}return''}
function excelPayload(type,o){if(type==='sosyalKulupler')return{ad:String(rowValue(o,'Kulüp Adı','Ad')).trim(),ogretmenIdler:teacherIdsByNames(rowValue(o,'Danışman Öğretmenler','Öğretmenler','Öğretmen')),sinifIdler:classIdsByNames(rowValue(o,'Sınıflar','Sınıf')),yillikPlanTarihi:excelDate(rowValue(o,'Yıllık Plan Son Tarihi')),toplumHizmetiTarihi:excelDate(rowValue(o,'Toplum Hizmeti Planı Son Tarihi')),aktif:rowValue(o,'Aktif')===''?true:truth(rowValue(o,'Aktif')),kontroller:Array(12).fill(false)};if(type==='belirliGunler')return{ad:String(rowValue(o,'Etkinlik Adı','Ad')).trim(),tarihBaslangic:excelDate(rowValue(o,'Başlangıç Tarihi','Tarih')),tarihBitis:excelDate(rowValue(o,'Bitiş Tarihi')),ogretmenIdler:teacherIdsByNames(rowValue(o,'Sorumlu Öğretmenler','Öğretmenler','Öğretmen')),aciklama:String(rowValue(o,'Notlar','Açıklama')).trim(),kontroller:[false]};if(type==='zumre')return{ogretmenId:teacherIdByName(rowValue(o,'Öğretmen')),brans:String(rowValue(o,'Branş','Ders')).trim(),sinif:String(rowValue(o,'Sınıf')).trim(),tarih1:excelDate(rowValue(o,'1. Dönem Son Tarihi','1. Dönem')),tarih2:excelDate(rowValue(o,'2. Dönem Son Tarihi','2. Dönem')),tarih3:excelDate(rowValue(o,'Yıl Sonu Son Tarihi','Yıl Sonu')),aciklama:String(rowValue(o,'Notlar','Açıklama')).trim(),kontroller:[false,false,false]};if(type==='sok')return{ogretmenId:teacherIdByName(rowValue(o,'Öğretmen')),sinif:String(rowValue(o,'Sınıf')).trim(),konu:String(rowValue(o,'Konu')).trim(),tarih1:excelDate(rowValue(o,'1. Dönem Son Tarihi','1. Dönem')),tarih2:excelDate(rowValue(o,'2. Dönem Son Tarihi','2. Dönem')),tarih3:excelDate(rowValue(o,'Yıl Sonu Son Tarihi','Yıl Sonu')),aciklama:String(rowValue(o,'Notlar','Açıklama')).trim(),kontroller:[false,false,false]};if(type==='bepPlani')return{ogretmenId:teacherIdByName(rowValue(o,'Öğretmen')),brans:String(rowValue(o,'Branş')).trim(),sinif:String(rowValue(o,'Sınıf')).trim(),yillikDersPlaniTarihi:excelDate(rowValue(o,'Yıllık Ders Planı Son Tarihi')),bepPlaniTarihi:excelDate(rowValue(o,'BEP Planı Son Tarihi')),aciklama:String(rowValue(o,'Notlar','Açıklama')).trim(),kontroller:[false,false]};if(type==='rehberlik')return{ogretmenId:teacherIdByName(rowValue(o,'Öğretmen')),sinif:String(rowValue(o,'Sınıf')).trim(),yillikPlanTarihi:excelDate(rowValue(o,'Yıllık Çalışma Planı Son Tarihi','Yıllık Plan Tarihi')),aciklama:String(rowValue(o,'Notlar','Açıklama')).trim(),kontroller:Array(12).fill(false)};if(type==='maarifRapor')return{ogretmenId:teacherIdByName(rowValue(o,'Öğretmen')),ders:String(rowValue(o,'Ders')).trim(),sinif:String(rowValue(o,'Sınıf')).trim(),aciklama:String(rowValue(o,'Açıklama','Notlar')).trim(),kontroller:Array(10).fill(false)};if(type==='digerEvrak')return{evrakAdi:String(rowValue(o,'Evrak Adı','Ad')).trim(),tur:String(rowValue(o,'Tür')).trim()||'Diğer',sinif:String(rowValue(o,'Sınıf')).trim(),tarih:excelDate(rowValue(o,'Tarih')),aciklama:String(rowValue(o,'Açıklama','Notlar')).trim(),teslimEdildi:truth(rowValue(o,'Teslim Edildi','Teslim'))};return null}
function validExcelRow(type,v){if(!v)return false;if(type==='sosyalKulupler'||type==='belirliGunler')return!!v.ad;if(type==='digerEvrak')return!!v.evrakAdi;if(type==='maarifRapor')return!!(v.ogretmenId&&v.ders&&v.sinif);if(type==='bepPlani'||type==='zumre')return!!(v.ogretmenId&&v.brans);if(type==='sok')return!!(v.ogretmenId&&v.sinif&&v.konu);if(type==='rehberlik')return!!(v.ogretmenId&&v.sinif);return false}
async function importExcel(type,file){await ensureXlsx();const wb=global.XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),ws=wb.Sheets[wb.SheetNames[0]],rows=global.XLSX.utils.sheet_to_json(ws,{raw:true,defval:''});let added=0,skipped=0;for(const o of rows){const v=excelPayload(type,o);if(!validExcelRow(type,v)){skipped++;continue}await global.CizelgelerService.kayitKaydet(type,null,v);added++}global.toast?.(`İçe aktarma tamamlandı: ${added} kayıt eklendi${skipped?`, ${skipped} satır atlandı`:''}.`);render(true)}
function chooseExcel(type){let input=document.querySelector(`[data-cizelge-excel-input="${type}"]`);if(!input){input=document.createElement('input');input.type='file';input.accept='.xlsx,.xls';input.hidden=true;input.dataset.cizelgeExcelInput=type;input.addEventListener('change',async()=>{const file=input.files?.[0];input.value='';if(!file)return;try{await importExcel(type,file)}catch(e){console.error('[CizelgeExcel]',e);global.toast?.('İçe aktarma hatası: '+(e?.message||e))}});document.body.appendChild(input)}input.click()}
function open(title=''){const next=typeFromTitle(title)||currentType;if(!next||!CFG[next])return false;currentType=next;return render(true)}
function close(){currentType='';closeModal();return true}
global.ClassicCizelgelerParity={open,close,render,openEdit,openBulk,printReport,importExcel,typeFromTitle,get currentType(){return currentType}};
})(window);
